"""Summarize saved matched5000 TRAIN logits; no inference, scores, or updates."""
import pathlib,json,hashlib,datetime
E=pathlib.Path(__file__).resolve().parent;R=E.parent;read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
p=E/'eos-location-effect-5000.json';new=read(p);prior_path=R.parent/'round35/execution/eos-location-effect-5000.json';old=read(prior_path)
assert new['actualUpdatesEach']==old['actualUpdatesEach']==5000
assert new['trainOnlyRows']==old['trainOnlyRows']and new['selectionSalt']==old['selectionSalt']and new['trainIndexSha256']==old['trainIndexSha256']and new['trainTokensSha256']==old['trainTokensSha256']and new['featureSha256']==old['featureSha256']
for label,key in [('coefficientZeroRound34','controlRound34'),('coefficientOneRound35','newRound35')]:assert new['results'][label]==old['results'][key]
record=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),actualUpdatesEach=5000,diagnosticSha256=sha(p),priorDiagnosticSha256=sha(prior_path),priorCoefficientZeroAndOneResultsExactlyReproduced=True,sameRowsSaltTrainIndexTokensAndBoundaryFeatures=True,posthocSelectedTrainRows=12,notSemanticOrGeneralizationEvidence=True,additionalOptimizerUpdates=0,codeSha256=sha(pathlib.Path(__file__)))
(E/'eos-location-control-reproduction.json').write_text(json.dumps(record,indent=2)+'\n')
lines=['# Matched5000 TRAIN-position EOS diagnostic','','Round36 remains in training. This compares existing coefficient0/1 rounds and the current coefficient0.3 round at exactly5000 actual updates each. It adds no training condition, optimizer update, heldout access, generation or semantic grade. All use the same fixed12 TRAIN rows and boundary masks chosen for the prior Round35 posthoc analysis. The old coefficient0/1 numeric results were reproduced exactly, including checkpoint SHA and every group statistic. Raw results and reproduction hashes are in execution/.','','| Positions / measure | R34 coefficient0 | R36 coefficient0.3 | R35 coefficient1 |','|---|---:|---:|---:|']
labels=['coefficientZeroRound34','coefficientPointThreeRound36','coefficientOneRound35']
for group,title in [('eligibleTrueTurnEnd','Eligible authentic utterance ends'),('nonNewlineOriginalContent','Original content excluding every newline-containing token'),('originalDialogueEos','Original dialogue-final EOS')]:
 gs=[new['results'][x]['groups'][group]for x in labels];assert len({g['positions']for g in gs})==1
 for key,description in [('meanEosProbability','mean EOS probability'),('eosArgmaxPositions','EOS argmax positions'),('meanOriginalGoldNll','original-gold NLL')]:
  vals=[str(g[key])if key=='eosArgmaxPositions'else f'{g[key]:.9f}'for g in gs];lines.append('| '+title+f' ({gs[0]["positions"]}) / '+description+' | '+' | '.join(vals)+' |')
lines += ['', 'At these measured positions, coefficient0.3 reduces the coefficient1 increase in EOS probability, content-position EOS argmax and original-gold NLL. Its EOS argmax count is0 at the67 eligible utterance ends, whereas coefficient1 gives37. At the1840 non-newline content positions it gives19, between coefficient0 (3) and coefficient1 (45). EOS on a content position is not by itself proof that an alternative continuation is wrong. The original dialogue-final EOS category contains only6 positions and is particularly small.','','The authentic-end objective keeps original newline CE and adds EOS CE with the same denominator. Ignoring other losses, other examples and parameter sharing, the isolated-position optimum has p(EOS)/p(newline)=coefficient. A lower coefficient therefore cannot be assumed to yield correct greedy stopping, even when it improves original-gold likelihood. This observation is consistent with that competition; it does not isolate all mediated changes in self-generated unlikelihood targets.','','Limits: selected TRAIN rows, correlated/possibly overlapping views, not a representative whole-TRAIN estimate, not independent replication, not an unseen test, and not free-generation evidence. The1867-position broader category includes27 newline-containing compound targets and must not all be called content interior. Do not infer improved meaning, fewer daily conversation loops or checkpoint adoption from these logits. No original gate, sampling, target, coefficient or selected-checkpoint rule changes in this round. Final selected/terminal full outputs and humanDEV99 still require evaluation.','']
(R/'EOS_LOCATION_DIAGNOSTIC.md').write_text('\n'.join(lines));print(json.dumps(record))
